in highp  vec3 vs_INTERP1;
layout(location = 0) out mediump vec4 SV_Target0;
vec4 u_xlat0;
mediump vec2 u_xlat16_0;
vec3 u_xlat1;
vec3 u_xlat2;
vec3 u_xlat3;
bvec3 u_xlatb3;
vec3 u_xlat4;
void main()
{
    u_xlat0.x = dot(vs_INTERP1.xyz, vs_INTERP1.xyz);
    u_xlat0.x = sqrt(u_xlat0.x);
    u_xlat0.x = float(1.0) / u_xlat0.x;
    u_xlat0.xyz = u_xlat0.xxx * vs_INTERP1.xyz;
    u_xlat1.x = dot(u_xlat0.xyz, hlslcc_mtx4x4unity_MatrixInvV[0].xyz);
    u_xlat1.y = dot(u_xlat0.xyz, hlslcc_mtx4x4unity_MatrixInvV[1].xyz);
    u_xlat0.xy = u_xlat1.xy * vec2(0.5, 0.5) + vec2(0.5, 0.5);
    u_xlat16_0.xy = texture(_MatcapTexture, u_xlat0.xy, _GlobalMipBias.x).xy;
    u_xlat1.xyz = _Color.xyz + vec3(0.150000006, 0.150000006, 0.150000006);
    u_xlat1.xyz = (-_Color.xyz) * vec3(_Multiply) + u_xlat1.xyz;
    u_xlat2.xyz = _Color.xyz * vec3(_Multiply);
    u_xlat0.xzw = u_xlat16_0.xxx * u_xlat1.xyz + u_xlat2.xyz;
    u_xlat1.xyz = (-u_xlat0.xzw) + vec3(1.0, 1.0, 1.0);
    u_xlat1.xyz = u_xlat1.xyz + u_xlat1.xyz;
    u_xlat2.xyz = _Color.xyz + vec3(vec3(_Spec, _Spec, _Spec));
    u_xlat3.xyz = (-u_xlat2.xyz) + vec3(1.0, 1.0, 1.0);
    u_xlat2.xyz = u_xlat0.xzw * u_xlat2.xyz;
    u_xlat2.xyz = u_xlat2.xyz + u_xlat2.xyz;
    u_xlat1.xyz = (-u_xlat1.xyz) * u_xlat3.xyz + vec3(1.0, 1.0, 1.0);
    u_xlatb3.xyz = greaterThanEqual(vec4(0.5, 0.5, 0.5, 0.0), u_xlat0.xzwx).xyz;
    u_xlat4.x = (u_xlatb3.x) ? float(0.0) : float(1.0);
    u_xlat4.y = (u_xlatb3.y) ? float(0.0) : float(1.0);
    u_xlat4.z = (u_xlatb3.z) ? float(0.0) : float(1.0);
    u_xlat3.x = u_xlatb3.x ? float(1.0) : 0.0;
    u_xlat3.y = u_xlatb3.y ? float(1.0) : 0.0;
    u_xlat3.z = u_xlatb3.z ? float(1.0) : 0.0;
;
    u_xlat1.xyz = u_xlat1.xyz * u_xlat4.xyz;
    u_xlat1.xyz = u_xlat2.xyz * u_xlat3.xyz + u_xlat1.xyz;
    u_xlat1.xyz = (-u_xlat0.xzw) + u_xlat1.xyz;
    u_xlat0.xyz = u_xlat16_0.yyy * u_xlat1.xyz + u_xlat0.xzw;
    SV_Target0.xyz = u_xlat0.xyz;
    SV_Target0.w = 1.0;
    return;
}

